# Common pattern: entry point defines router boundaries
def discover_entry_point(manifest: dict) -> str:
    if 'app' in manifest:
        return f"Web service initialized via {manifest['app']}"
    elif 'main' in manifest:
        return f"CLI entry point: {manifest['main']}"
    return 'Worker / library root'

print(discover_entry_point({'app': 'app.main:app'}))
print(discover_entry_point({'main': 'cli.py:run'}))

def parse_request(raw: dict) -> dict:
    return {'user_id': int(raw['id']), 'amount': float(raw['val'])}

def apply_business_rule(data: dict) -> dict:
    # Data flow: adds fee calculation
    return {**data, 'fee': round(data['amount'] * 0.02, 2)}

raw_payload = {'id': '101', 'val': '500.0'}
validated = parse_request(raw_payload)
result = apply_business_rule(validated)
print('Data flow transformation:', result)

# Tests reveal the specification:
def test_specification_example():
    # Test documents that negative transfers raise ValueError
    try:
        amount = -50
        if amount <= 0:
            raise ValueError('Must be positive')
    except ValueError as exc:
        print('Specification verified:', exc)

test_specification_example()
